INSERT INTO weekly_reports (report_id, assignment_id, week_number, tasks_completed, issues_challenges, lessons_learned, plan_next_week, status, plagiarism_score, is_anomaly) VALUES ('5a8b4467-72ce-4b02-9d5f-397351f9418b', '12667f81-7d4c-4016-9e07-2ef7b661117c', 3, 'Thiết kế database schema cho module quản lý nhân sự. Viết API CRUD cho entity Employee.', 'Môi trường test bị lỗi kết nối DB mất 1 buổi sáng, phải chờ team DevOps xử lý.', 'Học được cách tổ chức thư mục code sạch sẽ theo Clean Architecture.', 'Hoàn thành nốt báo cáo thực tập để nộp về trường.', 'APPROVED', 0.0731, FALSE);
INSERT INTO report_feedbacks (feedback_id, report_id, reviewer_id, feedback_text, action) VALUES ('4ac74ee6-37af-4361-a120-4ca94e6f6d39', '5a8b4467-72ce-4b02-9d5f-397351f9418b', '79fbe268-0398-4344-b008-099209419986', 'Đã review code của em trên Git, tư duy logic khá ổn nhưng cần chú ý optimize vòng lặp.', 'APPROVED');
